#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""t2084《三宝感应要略录》白话译本构建（171段，宋 非浊集）"""
import json, os

_h2s = json.load(open('sutras/hant2simp.json', encoding='utf-8'))
def cc(s):
    return ''.join(_h2s.get(ch, ch) for ch in s)

TID = 't2084'
TITLE = '三宝感应要略录'
TRANS = '宋 非浊集'
INTRO = ('《三宝感应要略录》（宋 释子非浊集，3卷）是宋代佛教感应故事总集。全书以「灵像感应」为佛宝、'
         '「尊经感应」为法宝、「菩萨感应」为僧宝，蕳为三聚分作三卷：卷上佛宝聚（佛像、舍利、造塔造寺等灵应），'
         '卷中法宝聚（华严、阿含、律藏、方等、涅槃、维摩、法华、般若、金刚、仁王、金光明、无量义等经与'
         '药王、随求、尊胜等陀罗尼的书写受持读诵灵应），卷下僧宝聚（文殊、普贤、弥勒、观音、地藏、大势至、'
         '药王药上、龙树、无著世亲等菩萨感应）。所辑多标明出处（西域记、冥祥记、梁高僧传、法苑珠林、慈恩传等），'
         '为研究中国佛教感应信仰与三宝崇拜的重要文献。')

src = json.load(open(f'sutras/{TID}.json', encoding='utf-8'))
allc = [(c.get('chapter') or '', (c.get('text') or '').strip()) for c in src['content']]
allc = [(ch, t) for ch, t in allc if t]
assert len(allc) == 171, f'content mismatch: {len(allc)}'
paras = [t for _, t in allc]
TITLES = [cc(ch).replace('「', '').replace('」', '').strip() for ch, _ in allc]
FIX = {2: '卷上·释子非浊集', 54: '卷中·释子非浊集', 128: '卷下·释子非浊集'}
for k, v in FIX.items():
    TITLES[k] = v
assert all(TITLES), [i for i, t in enumerate(TITLES) if not t]

YIJIE = [
    "《三宝感应要略录》总序。以灵像感应为佛宝、尊经感应为法宝、菩萨感应为僧宝，是浊世末代断恶修善之目足；信为道源功德之聚，行为要路解脱之基，故略表肝要、粗叙奇瑞，蕳为三聚分为三卷，易见易寻。",
    "卷上·佛宝聚目录（第一优填王、波斯匿王释迦金木像感应，至第五十金地国王治古寺延寿感应）。",
    "卷上卷首题记：释子非浊集。",
    "第一·优填王波斯匿王释迦金木像感应。释迦成道八年上升忉利天为母说法，人间四众思慕忧苦，优填王敕巧匠（毘首羯摩化身作匠）以纯紫栴檀造坐像高五尺，波斯匿王以紫磨金造五尺像，阎浮提始有此二如来像。如来下天，木像起迎礼拜、佛为摩顶授记「我灭后千年外当于此处为人天作大饶益」；佛言前佛灭后造像者皆生十方佛前、无一人犹在生死，唯造菩萨像者故留在世。",
    "第二·影胜大王画释迦像感应。佛世摩揭陀影胜王与胜音城仙道王互赠宝物，仙道王赠五德宝甲，影胜王无物可酬，大臣行雨献策于大疊上画世尊像、并书三归五戒十二缘生及二颂，遣使送往。仙道王初怒欲伐，后观像闻法悟缘生得初果，遣使求见比丘，佛遣迦多演那与五百比丘、五百比丘尼往化，仙道王后舍位出家。",
    "第三·汉土最初释迦像感应。汉明帝梦金人，遣使天竺写致经像，使者蔡愔将西域沙门迦叶摩腾赍优填王画释迦佛像至，帝如梦所见，遣画工图数本于南宫清凉台、高阳门等处供养，又于白马寺壁画千乘万骑绕塔像。",
    "第四·梁祖武帝迎请释迦像感应。梁武帝天监元年梦檀像入国，募郝骞等八十人往迎；舍卫王令三十二匠更刻檀像，像顶放光、降微雨异香。骞等负像历艰渡海，遇险念像得僧授澡灌令饮得饱，天监十年达扬都，帝徒行四十里迎还太极殿，斋僧度人大赦，帝由此蔬食断欲。",
    "第五·造释迦像死从阎罗王宫被还感应。凝观寺僧法庆开皇三年造夹纻释迦立像未毕而卒；宝昌寺僧大智死三日苏，说见阎罗王前此像来礼拜，像责王「法庆造我未毕，奈何令死」，王查其命未合终而食断已尽，令给荷叶；法庆遂亦苏，常食荷叶，其像屡放光明。",
    "第六·陇西李太安妻为安造释迦像救死感应。唐李太安途宿被盗刺颈，恍如梦，见池西金像化为僧、以手摩其头疮去痛；归家见妻所造佛像背有朱污，正与所见僧背红缯补处相合，于是叹异，崇信佛法，益年不死。",
    "第七·悟真寺惠镜造释迦弥陀像见净土相感应。悟真寺释惠镜造释迦、弥陀二像供养，梦沙门授钵令见净土，佛言前导沙门即所造释迦像、佛即所造弥陀像，以父（释迦教化娑婆）、母（弥陀净土摄受）喻；后梦沙门告十二年后当生净土，七十九而卒，邻房僧梦圣众来迎。",
    "第八·健陀罗国二贫人各一金钱共画一像感应。健陀罗国二贫士各持一金钱共请画工画佛像，画工受二人钱共画一像，二人同日俱来礼敬，画工同指一像谓二人；二人相视有疑，画工言像必神变，言声未静像现灵异、分身交影、光相照示，二人悦服欢喜。",
    "第九·唐幽州虞安良助他人造释迦像免苦感应。幽州渔阳虞安良以杀生为业，三十七岁游猎落马闷绝，见马头牛头以火车投其身，有彩服僧洒水拒火并领见阎罗王，僧言其兄安通发心造释迦像、良依缘投钱三十文助之，故来相救；良感悟，过兄家见像全同所见，遂自造像。",
    "第十·北印度沙门达磨流支感释迦像惊感应。沙门常慜至北印度僧伽补罗国见石塔旁精舍刻檀释迦弥勒像；法爱（达磨流支）欲造慈氏像，外国沙门劝其先造释迦像（慈氏是释迦弟子、三会得脱之人）；法爱坚持不改，梦金人责其轻慢本师、若不造释迦像则不能生兜率亦不能往生净土；法爱遂舍衣钵资造此二像。",
    "第十一·鸡头摩寺五通菩萨请阿弥陀佛图写感应。相传天竺鸡头摩寺五通菩萨往安乐世界，请阿弥陀佛为娑婆欲生净土而无佛像之众生图写形像，佛许之；菩萨还时其像已至，一佛五十菩萨各坐莲花在树叶上，菩萨取叶所在图写流布远近。",
    "第十二·隋安乐寺惠海图无量寿像感应。隋江都安乐寺释惠海以净土为业，齐州僧道铃赍天竺鸡头摩寺五通菩萨所图无量寿像来；海冥会素情、深怀礼忏、睹神光，于是摸写愿生彼土，六十九岁夜起面西礼恋跏趺而逝，颜色怡和。",
    "第十三·隋僧道喻三寸阿弥陀像感应。隋僧道喻念阿弥陀佛、造栴檀三寸像，死后七日苏，说见宝池莲花、贤者入坐，己身绕花不开；弥陀告其忏悔沐浴、造像因何太小，喻答「心大即大，心小即小」，像即遍虚空，遂一心忏悔，明星出时化佛来迎而终。",
    "第十四·并州张元寿为亡亲造阿弥陀像感应。并州张元寿断杀生业、念阿弥陀佛，为救双亲造三尺像供养，梦室中有光、乘莲台者二十余人，其父母告以堕叫唤地狱而蒙所造像往地狱说法，同業二十余人皆离地狱生净土。",
    "第十五·释道如为救三途众生造阿弥陀像感应。并州释道如发愿先度他、为救三途众生造阿弥陀丈六金像，梦冥官持阎罗王随喜牒书，谓其像入地狱教化众生、宛如生佛放光说法，地狱业轻者皆离苦得乐；道如禅定中像胸放光，或梦其现金色身入地狱说法。",
    "第十六·宋释僧高造丈六无量寿像感应。宋江陵长沙寺释僧高志期西方、愿造丈六无量寿像，欲取湘州铜溪山庙铜器，振锡告蟒蛇「汝前世罪业受蟒，吾造丈六无量寿像，幸开路」，蛇举头引身而去；高取得铜器铸像，元寿九年毕功，神表端严、威光伟曜。",
    "第十七·阿弥陀佛化作鹦鹉鸟引安息国感应。安息国人愚痴不识佛法，有金色鹦鹉鸟能作人语，教诸人唱佛名可为食、身肥力强，劝令念佛即飞腾虚空指西方而去；王臣叹异谓阿弥陀佛化鸟身引摄边鄙，即立精舍号鹦鹉寺，此后安息国人少识佛法、往生净土者多。",
    "第十八·阿弥陀佛作大鱼身引渔人感应。执师子国西南绝岛五百余户捕鸟为食、不闻佛法，数千大鱼作人语唱南无阿弥陀佛，渔人依唱名取鱼；一渔人寿尽命终生极乐，三月后乘紫云来告「其大鱼者，阿弥陀如来化作，劝进念佛三昧」，鱼骨皆是莲花；执师子国狮子贤大阿罗汉传说此事。",
    "第十九·信妇言称阿弥陀佛名感应。天竺阿输沙国一婆罗门愚痴不信，其妇净信解念佛定，劝夫念佛，夫依妇言三年而卒；死后五日苏，说入镬汤地狱时闻金鼓声（即妇所击之金鼓）而唱南无阿弥陀佛，地狱顿变凉池、莲花弥满，声所及罪人皆生净土，阎王放还令传说人间。",
    "第二十·十念往生感应。一人性粗险不信因果、常以杀猎为业，临终见地狱苦具及所杀众生来索命，悔而请僧救度，闻经说「十念得往生」，遂左手执火、右手握香，面向西方至心念佛，未满十念即告众「佛从西来、授我花座」而卒。",
    "第二十一·释双惠图造阿閦佛感应。隋开皇中释双惠图阿閦佛像十体、又造同像十二体，专心祈请，梦二僧（自称日光、喜辟）赞其归依阿閦佛、一生入不退位得生欢喜，临终启众往生欢喜国。",
    "第二十二·造药师形像得五十年寿感应。天竺一婆罗门富贵无子，生子相者言寿止二年，亲友沙门教依七佛法造药师如来形像如法供养，父夜梦冥道捧札来言「依七佛法造像供养，更得子五十年寿」。",
    "第二十三·贵姓祈请药师灵像得富贵感应。天竺一贵姓贫乏乞食、人称闭门，诣药师灵像寺右绕佛像、至心悔过断食五日，梦像出妙色身告其宿业颇灭、必得富饶、可还父母旧宅；依言以杖掘地得伏藏，一年内得富贵。",
    "第二十四·贫人以一文铜钱供养药师像得富贵感应。唐边州一贫女孤独自活，唯有一文铜钱，思此钱不可为一生资粮、当供佛像，即往伽蓝供养药师灵像；经七日邻县富家妇死求女不得，复祈请同寺像，梦感以此孤女为妇，共得福寿生三男二女。",
    "第二十五·破戒者称药师名戒还得净感应。一比丘往西域问得戒源由，遇阿罗汉升兜率问弥勒，弥勒取金花验边地僧尼得戒之相；又问受戒已后犯者如何远得所失，答「东方有净土名净琉璃、佛名药师，以本愿故破戒称名必得净戒」。",
    "第二十六·夏侯均造药师形像免罪感应。夏侯均显庆二年受重病昏乱而死，被配作牛身、于磨坊苦使二十四日，自诉曾三度受戒、兼受持药师经、自造形像，冥司勘其受戒等是实不虚，始得免罪还苏。",
    "第二十七·药师如来救产苦感应。淄州一女人怀孕十二月不得产、身体疲苦骨髓疼痛、举声啼哭，受沙门迈公教称药师名，梦佛自来救，弥信随唱，苦渐息而产一男。",
    "第二十八·温州司马家室亲属一日之中造药师像七躯感应。温州司马得长病欲死，死后亲属知识至心归依药师，一日造药师形像七躯如法供养，至第二日司马闷绝还活，说见琰魔王，王因亲属造七佛像而许其延寿放还。",
    "第二十九·造毗卢遮那佛像拂障难感应。释常慜至中印度鞞索迦国见毗卢遮那像、灵验甚著，昔此国神鬼乔乱、人民荒废，国王依尼乾子占察造此毗卢遮那像（左黄金、右白银、高二十丈），夜叉童子遂驱荒神恶鬼出国界，方无障难。",
    "第三十·圣无动尊自称无价驮婆感应。南天竺王子厌世出家，弘持正法、诵圣无动明王，独步旷野，明王现身共为伴、自称无价驮婆（驮婆此云奴婢、不用钱买故名无价），奉事修行者如世尊弟子给侍，肩系帛巾为其表帜。",
    "第三十一·释含照图写千佛像感应。唐兴善寺释含照发愿图千佛像，纔写七佛而不知余九百九十三佛威仪手印，精诚祈请、流泣悔过，梦九百九十三佛现于木叶，欢喜图写流布传世。",
    "第三十二·胎藏曼陀罗相传感应。毗卢遮那如来说大悲胎藏曼陀罗王，金刚手传受佛教，经数百年传中印度世无厌寺达磨掬多，再付斛饭王玄孙释善无畏；无畏开元七年携曼陀罗图来此国，为玄宗国师、译大教大曼陀罗、设大道场，诸尊放光、天雨细花。",
    "第三十三·金刚界曼陀罗传弘感应。金刚萨埵于毗卢舍那佛前受金刚界大曼陀罗法义，后数百年传龙猛菩萨，又传龙智，再传金刚智；金刚智于开元八年至京邑，广弘秘教、建曼陀罗，依法作成皆感瑞应。",
    "第三十四·建金刚界灌顶道场祈雨而得感应。金刚智三藏年三十一往南天竺从龙智受五部灌顶诸秘密藏，后南天竺三年亢旱、草木枯死，王遣使迎请于宫中建金刚界灌顶道场请雨，甘泽流澍，王臣欣庆，为王造寺安置。",
    "第三十五·礼拜金刚界大曼陀罗感应。津州一孤女愚痴不信、不识因果，五十有七遭疾而死，六日方醒，流泪自责，说入铁火地狱时狱司白阎魔王，王捡书谓此女昔于弘和上室礼拜金刚界大曼陀罗灌顶坛场，以此力故遣还人间。",
    "第三十六·念胎藏大曼陀罗感应。大兴善寺传法灌顶阿阇梨惠应有一沙弥从七岁师事和上，附船渡新罗遇暴风船覆，五十余人没海漂寄；沙弥一心念胎藏圣众，梦虚空圣众如星散光、身忽在岸上，五十余人皆不溺没同在，知救难之力不可思议。",
    "第三十七·汉明帝时佛舍利感应。汉明帝弘法立寺，其时西域所将舍利五粒五色，直上空中旋环如盖、映蔽日光。",
    "第三十八·吴王围寺执僧舍利浮光于钵上感应。孙皓集沙门、陈兵围寺欲诛废，僧会法师请以七日现神，以铜钵盛水置庭中，舍利明照浮于钵上；以百钧之槌击之不损，光明耀彩，皓伏地投诚、劝营斋讲。",
    "第三十九·唐阿得造塔放还感应。唐阿得死三日还苏，说被两人挟至冥府见府君（阎王），府君因其家起浮图寺塔供养道人而称其大福德、加寿三十五年，令案行地狱十狱与福舍，然后还阳。",
    "第四十·五级未就刑利刃断感应。荥阳高苟年五十被捕、分必受死，同牢劝其诵观世音，苟发心誓舍恶行善、专念观音，若得免脱愿起五层佛图、舍身作奴供养众僧；旬日用心锁自解，临刑举刀未下而刀折刃断，奏得原免。",
    "第四十一·庙神奉绢世高为起塔离蟒身感应。沙门安世高至宫亭湖庙，神告其昔出家好行布施而不持戒、今为湖神，有绢千匹在石函中可为之立塔营三宝；神现大蟒蛇身悲泪如雨，世高取绢物起萧寺、于瓦官寺起塔二重，后梦神来云已脱蟒身。",
    "第四十二·须达长者图精舍地感应。须达长者与舍利弗往图精舍，舍利弗见其始于此地住而六欲天宫殿已成，示以六天；须达言愿生第四天（少欲知足、恒有补处菩萨说法），言竟余宫悉灭，唯第四天宫殿湛然。",
    "第四十三·建立精舍地感应。佛于祇洹精舍放大光明遍照三千大千世界，光中见百亿四天下黄金地处处遍满；须达问故，佛言涅槃后正像末时四部弟子建寺堂处即光明所住黄金地，彼等以白毫功德分作佛事，决定不堕四恶趣、必当得佛。",
    "第四十四·沙弥以杖加精舍为壁木延寿感应。罽宾国精舍一沙弥年十三，尼乾子占其寿唯二年，后见其延寿五十年；上座三明大阿罗汉入定观知，因沙弥夏初众僧修营精舍壁少一木、即持古杖加之成壁，以此因缘延五十年寿。",
    "第四十五·拂精舍庭生天感应。如来在世时有天人，佛为说四谛法得法眼净；佛告阿难，此天人是须达居士造精舍后所遣拂寺庭、扫道路之奴，乘此善根生忉利天，来下听法得法眼净。",
    "第四十六·于父母故宅地造精舍感应。尊者夜周多归旧里、于父母故宅地建立佛精舍；夜分有百千天子来下供养，自言是尊者父母，以恶业堕地狱、因尊者出家日生天，见宫殿动摇、光明倍胜故来供养。",
    "第四十七·室罗伐悉底国寺感应。室罗伐悉底国一精舍高六十余尺，其东有天祠量等精舍，日旦流光天祠之影不能蔽精舍，日将落则精舍之阴反覆天祠。",
    "第四十八·贫儿以木叶戏作寺延寿感应。昔阿罗汉路遇一贫儿、观其寿止三日，第三日复遇贫儿，入定观知其有六十年寿；又观善根，知贫儿与诸乞儿共戏时拾木叶为寺之报，为人说之，闻者生信。",
    "第四十九·比丘补壁孔延寿感应。昔一比丘死时将至，入僧伽蓝见壁有孔，即以泥团补塞，由此增其寿命。",
    "第五十·金地国王治古寺延寿感应。昔相师占金地国王，却后七日必当命终；王后日游猎见一故寺破坏，即生悲心速修治之，得三十年寿。",
    "卷中·法宝聚目录（第一将读华严经以水盥掌水所沾虫类生天感应，至第七十二诸王写一切经感应）。",
    "卷中卷首题记：释子非浊集。",
    "第一·有人将读华严经以水盥掌水所沾虫类生天感应。执师子国第三果沙门释迦弥多罗（能友）至京师大原寺，劝诸僧转读华严，谓闻华严题目者决定不堕四恶趣；又传遮拘槃国精舍读华严，夜中有大光明，百千天人（即精舍旁虫类，因沙门盥掌读经之水霑及而舍命生忉利天）来下报恩，王遂立制偏重大乘、不流通小法。",
    "第二·毘瑟寺小乘师以花严置阿含下恒在其上感应。南天竺毘瑟奴僧伽蓝诸小乘师不敬大乘法师所留华严经一袟，投之井中，见井中光明如烈火、久在水中不霑湿，方信是佛说；仍置经于阿含等经律之下，明旦辄见在上，如是数返，小乘诸师惊歎投地懺谢回心，专共受持华严。",
    "第三·释灵干讲花严经见天宫迎改生花藏界感应。释灵干每讲华严，开皇十七年遇疾闷绝而后醒，说生兜率天见休、远二法师坐花台，告其诸弟子皆当生此；干素奉华严、作莲花藏世界海观及弥勒天宫观，临终见大水遍满、花如车轮而坐其上，所愿满足而逝。",
    "第四·唐朝散大夫孙宣德发写花严愿感应。孙宣德发愿造华严经、间生不信舍废造恶，后射猎落马闷绝，见阎魔王责其所杀禽兽诉命；有童子自称善财至王所，言宣德发造华严未果、所愿时无不信心，岂以后恶捨前善，王遂放还；宣德悔悟尽所有书写华严，八十六而卒，告亲友「吾写华严，生兜率天，奉事慈氏」。",
    "第五·东市行证为亲写华严救苦感应。雍州康阿禄山死后五日苏，说冥道中见东市药行人阿容师（生时煮鸡子与七百人、入镬汤地狱），凭嘱其第四子行证写华严经一部可令七百人解脱；禄山往告行证，证大悲感，于西大原寺写经，初写之夕合家同梦容师欢喜来告，永隆元年写毕设供，禄山见容师等七百鬼徒来礼三宝、忏悔受戒、改报天堂而去。",
    "第六·王氏感地藏菩萨感应。京师王氏（名定藏）无戒行、不修善，文明元年因患致死，被引至地狱门；见一僧云是地藏菩萨，教其诵一偈「若人欲了知，三世一切佛，应当如是观，心造诸如如来」，谓诵此能排地狱；王氏尽诵，入见阎罗王，王问功德，答唯受持一四句偈，王遂放免，诵偈时声所及受苦之人皆得解脱。",
    "第七·空观寺沙弥定生见红莲地狱谬谓华藏世界感应。沙弥定生不诵经戒、恣误僧事，入红莲花地狱而谬谓华藏世界，欢喜称华藏妙土，其时地狱变为花藏、受苦之人皆坐莲花；狱官白阎魔王，王言此是华严大不思议经力，即说偈赞「归命华严不思议经……诸地狱器皆为花藏」。沙弥一日一夜始苏自说此缘。",
    "第八·龙子从僧护比丘诵习阿含经感应。佛世舍卫国五百商人入海求宝，请僧护比丘为闻法师，龙王现身请僧护入宫，其四龙子各学一阿含（增一、中、杂、长），六月诵尽；僧护以其在畜生道无轨则心而呵，龙王白言四龙各有声毒、见毒、取毒、触毒故不得如法出声受持，护师命故。",
    "第九·新罗僧俞诵阿含生净土感应。新罗僧俞少出家归心净土，见诵持阿含者辄毁呵令捨；梦至极乐东门被天童子以宝杖驱出，谓小法灭没即大教灭相、以小法为梯登大道是汝国式，轻慢阿含不可入大乘门；梦觉悲泣悔过，兼持诵四阿含，得净土迎，弟子梦其坐莲花言「我兼诵阿含、先得小道，不久还入大」。",
    "第十·书写阿含经生天感应。如来灭后一百年中，夜分有一天人放光来下阿难塔所散花供养；近护大阿罗汉（阿育王师）问之，天答昔书写四阿含得生忉利天、是阿难恩故常来供养，并言同業者百千人，其中持增一阿含生天甚多。",
    "第十一·乾陀卫国阿罗汉昔闻阿含感应。乾陀卫国瞿摩夷精舍大阿罗汉名富那舍，六通三明、昼夜诵中阿含不废；自言入宿住三昧观先业，昔生在犬中随比丘而行、闻比丘诵中阿含而生乐不吠，乘此一善生婆罗门家、出家得阿罗汉果，故恒诵不废。",
    "第十二·五百蝙蝠闻阿毗达磨藏感应。昔南海之滨枯树中五百蝙蝠聚居，商人止树下聚薪温火，树燃，一贾客夜诵阿毗达磨藏，蝙蝠为火困而爱法音忍不去，命终得人身、捨家修学小乘法证圣果；即迦腻色迦王与胁尊者召集作毗婆沙论之五百贤圣。",
    "第十三·鼠闻律藏感应。罽宾国末田地阿罗汉精舍一阿罗汉，三明六通、持戒律清高，恒呵门徒勤修戒律；自言昔依恶业受鼠身住石窟，闻一比丘夜诵律藏，乘此善根得人身、成阿罗汉，故戒律精明。",
    "第十四·受持律藏感天感应。罽宾国可维精舍二比丘，一人持律藏、一人持论藏，人皆以妙食供律师，夜分天人来礼拜持律比丘而不礼持论比丘；持论比丘忿恚，天呵言「戒律开人天道乃至涅槃道」，持论比丘遂精勤修习，俱得初果。",
    "第十五·释迦昔得大集经一函灭罪感应。释迦昔无数劫中为凡夫名遮他，造诸恶行、害父爱母，出家学道三十七年而五逆障不得道，后于山窟得大集法悦捨苦陀罗尼经一函，知此经能除百亿劫生死五逆大罪、受持读诵者终不堕三途，遂修习读诵，飞行无碍、得见十方诸佛。",
    "第十六·并州比丘道如唯闻方等名字生净土感应。并州比丘道如不修念佛、不持戒、畜不净物、身犯不悔，六十一中风而死，三日苏，说观音、势至来示：汝不修净土业、唯闻大乘方等十二部经名字，以此因缘罪垢微薄，余命未尽、十二年后将生净土；遂捨所有造方等大集、兼修念佛，第十二年正月十五卒，音乐天花。",
    "第十七·昙荣僧定二人行方等忏法得记感应。唐潞州法住寺释昙荣贞观七年行方等悔法，沙门僧定于道场见大光明、七佛现身，六佛皆言「以汝罪消故来为证，然非本师不与授记」，末佛自称释迦牟尼、为授记「昙荣于贤劫中名普宁佛，汝（僧定）后当作佛亦为普明」。",
    "第十八·隋朝智者大师讲净名经感应。隋智者大师讳智顗，生时地涌一山号大贤、终时山即随没为大贤湖；讲净名经时忽见三道宝阶从空而下、阿閦佛土一会俨然而现，十数梵僧执香炉入堂绕顗三匝，赞「善哉智顗，玄悟佛意，吾来影向，感应如是」。",
    "第十九·宋临淄释普明诵维摩经感应。宋临淄释普明诵法华、维摩二经，诵维摩时闻空中唱乐，又善神咒、所拯皆愈；乡人王道真妻病请明入内，妇便闷绝，俄见一物如狸长数尺。",
    "第二十·会稽山阴书生写维摩经感应。会稽山阴一书生身有少疾，发愿写维摩经，立题之夜梦天女摩其书身、觉而疾愈；为亡亲写一部，梦父（堕黑暗地狱）告以造经光明照身、苦息生天，母（堕饿鬼）写佛国品离苦生无动国；又梦阎魔法王赐命二十年，七十九而卒、身金色。",
    "第二十一·法祖法师为阎罗王讲首楞严经感应。帛远字法祖，于长安造精舍、以讲习首楞严经为业；有李通死而更苏，说见祖法师在阎罗王处为王讲首楞严经，无量罪人闻师讲声生第二天，祖自云讲竟应生忉利天。",
    "第二十二·光宅寺云法师讲胜鬘经降雨感应。梁武帝欲祈雨，志公言「请光宅寺云公讲胜鬘经，雨降受润自足」；即请讲，雨遂降。",
    "第二十三·贫女受持胜鬘经现作皇后感应。佛灭度三百年中阿输阇国一贫女，六亲俱无、拾薪活命，余暇受持胜鬘经；入山采薪疲卧山中讲经，云盖其身，国王游猎见而异之，近见端正，欢喜还宫立为皇后，此经遂于此国再兴。",
    "第二十四·道珍禅师诵阿弥陀经生净土感应。梁朝道珍念佛作水观，梦百人乘船欲往西方，珍欲附载而被拒，船上人言「师业未诵弥陀经、并营浴室」；珍乃诵经浴僧，后又梦白银楼台相报、定生西方，临终夜山顶如列数十炬火、异香满寺。",
    "第二十五·昙鸾法师得观经生净土感应。齐朝昙鸾法师得此土仙经欲访陶隐居学仙术，逢三藏菩提问「佛法中有长生不死法否」，三藏唾地惊言此土无长生法、纵得延寿年尽须堕三有，即将无量寿观经授鸾「此大仙方，依而行之长得解脱」；鸾遂焚仙经，半夜感龙树菩萨说偈，寿终执炉面西念佛，闻空中音乐西来。",
    "第二十六·并州僧感受持观经阿弥陀经生净土感应。并州比丘僧感持观无量寿经、阿弥陀经为业，梦身生羽翼（左观经文右阿弥陀经文）欲飞尚重，觉而弥诵两经；三年后梦羽翼既长，又二年梦身轻飞腾到极乐边地，佛告其还娑婆每日诵四十八卷满一千日方生上品；如说修行三年而终，卧处生九茎莲花七日不萎。",
    "第二十七·西印度小国讲金光明经敌国得和感应。西印度一小国请摩腾边尊者讲金光明经，邻国兴师来侵，既将践境辄有事碍、兵不能进；彼国密遣使觇，见群臣安然共听大乘经、明地神王护国之法，于是请和求法，俱得安稳。",
    "第二十八·中印度讲金光明最胜王经感应。中印度奔那代弹那国如来灭后八百年中荒芜饥疫、妖死满路，智臣劝王讲金光明最胜帝王典；王请法师一夏讲经五返，梦诸童子执杖追打恶鬼驱出国、又梦大力鬼神掘地甘水涌出，疾疫顿息、五谷丰稔，未出一年国民富足。",
    "第二十九·温州张居道冥路中发造金光明四卷愿感应。温州治中张居道因杀猪羊鹅鸭，未逾一旬得重病便死，经三夜活，说被四人追缚见冥官，猪羊等三十余头共讼其枉相屠害；冥使教其为所杀生发心造金光明经四卷，述愿状而阎王欢喜、放归生路。闻此因缘发心造经、断肉止杀者众。",
    "第三十·则天皇后供养金光明最胜王经感应。三藏法师义净游西域三十余国，天后证圣元年还至阿洛；长安三年十月四日于西明寺译经，同月十五日于西明寺供养，施百尺幡二口、四十九尺幡四十九口、绢百匹及香花等七宝庄严，其时紫云盖寺、经卷放光、大地微动、天雨细花。",
    "第三十一·梓州姚待为亡亲自写大乘经感应。梓州郪县姚待长安四年丁忧，发愿为亡亲自写四大部经（法华、维摩各一部，药师经十卷，金刚般若一百卷）；日午有鹿突门而入立经案前举头舐案，又有屠儿李迴奴取般若经驰去。邻家梦鹿是待母、屠儿是待父，各依业受异身、来受其化。",
    "第三十二·唐张谢敷读诵药师经感应。唐谢敷姓张氏，顿得重病，妻妾请众僧七日七夜读诵药师经；满夜敷梦有众僧以经卷覆其身上，觉后平复如故。",
    "第三十三·唐张李通书写药师经延寿感应。张李通年二十七，相师言其寿短不可过三十一，李通忧愁依投迈公；迈公授唐三藏译药师经令敬心书写受持，通请经卷精诚自写，因世务相逼纔得一卷，相师再见惊叹其顿得三十年寿。",
    "第三十四·写大毗卢遮那经感应。昔北天竺勃鲁罗国城北有大石山，半腹有藏秘法之窟，每年七月众圣集会、数千猿猴捧经出晒；暴风吹一梵箧落下，采樵人得而献王，有大猿来索经、欲殒身自害，王许与通融受桝、缮写及限还之，王唯太子相传其本不流于外。",
    "第三十五·书随求陀罗尼系颈灭罪感应。昔一苾刍心怀净信而违犯制戒、将现前僧物与僧祇众物入己用，后遇重病受大苦恼，一婆罗门为大悲愍书此随求大明王陀罗尼系其颈下，苦恼皆息；苾刍命终生无间狱，因陀罗尼带于身上，纔入地狱诸受罪者苦痛悉得停息、阿鼻猛火由此威德悉皆消灭。",
    "第三十六·尊胜陀罗尼经请来感应。北印度罽宾国沙门佛陀波利（觉护）闻文殊在清凉山、远涉流沙躬来礼谒，见一老翁从山而出，劝其还西国取佛顶尊胜陀罗尼来流传此土（此土众众多造诸罪、出家之辈亦多所犯，此法除罪）；波利惊愕，遂返归本国取得经来，入于五台山，于今不出。",
    "第三十七·童儿闻寿命经延寿感应。唐玄宗开元末有一相者闻声知寿，于资圣寺闻门外童儿声，唯知其寿止今日；次日复闻前童儿，已延至七十余岁，生出奇念，问其由致，童儿答「吾今夜寄宿僧房，闻寿命经，更无余事」。",
    "第三十八·乌耆国王女读诵般若心经感应。昔乌耆国疾疫流行，王女典韦怀孕既久而母被重病、胎子既死，女惧惶闷绝、无所仰凭，昼夜读诵般若心经；由诵经力，胎子复生、安隐产生、疗病平成，儿生而恒诵摩诃般若波罗蜜，三岁能说般若了义，七岁通达三藏，举国读诵、病疾不兴。",
    "第三十九·毕试国王写诵般若心经感应。昔毕试国王族断嗣、役属邻境，众怨王互来侵逼；有圣主名听祐，思般若心经是佛法验，令国内男女大小各写诵般若心经，三年之间每旦各诵，龙神悦怡，诸国来侵者军众死落、群贼自然落失，毕试国遂平定，历十年成大国。",
    "第四十·遍学三藏首途西域每日诵般若心经三七遍感应。玄奘法师（本名袆）贞观三年杖锡西行，每日诵般若心经三七遍、立誓求大法，周游西宇十七年、见闻百三十八国，凡有留难处诵般若心经及念观世音必免怖畏；十九年正月还长安，获经论六百五十七部，三藏自云皆是般若心经及观音力。",
    "第四十一·大般若经翻译时感应。显庆五年正月一日起首翻大般若经，梵本二十万颂；学徒请删略，法师将顺众意如罗什所翻，即梦极怖畏事相惊诫，觉而还依广翻；夜见诸佛菩萨眉间放光照触己身，又见手执花灯供养诸佛；遂一如梵本、校三本以定之。翻严净佛土品时，玉花寺主惠德及翻经僧喜尚同梦寺内庄严、无量僧众供般若经，殿侧双李树非时数数开花、花皆六出。",
    "第四十二·大般若经最初供养感应。玉花寺都维那沙门寂照庆贺翻译功毕闻于皇帝，龙朔三年十月三十日设斋会供养，请经从肃成殿往嘉寿殿，般若放光照触远近、天雨妙花、有非常香气；寂照梦千佛在空同音说偈赞般若佛母、书写受持读诵者必尽生死际，白三藏，三藏言此是经中现千佛。",
    "第四十三·唐乾封书生依高宗敕书大般若经一帙感应。唐高宗乾封年中一书生遭疾而死，一日二夜始苏，说有赤服冥官以文牒召至大城门，息诤王见其右手放大光明直至王前，王惊问功德，捡书知公依高宗敕写大般若经十卷、右笔而写故右手放光，王遂放还；书生寻光而还，捨所有写六百卷。",
    "第四十四·东印度三摩咀吒国转读大般若王供养感应。澧州僧哲禅师浮舶西域，巡礼至东印度三摩咀吒国，王名曷罗社跋吒深敬三宝，每日造柘摸泥像十万区、读大般若十万颂、用鲜花十万供养；王城僧居四千计人皆受王供养，每日晨朝僧入寺合掌疾行，大王奉问、僧答呪愿，是大般若之力。",
    "第四十五·并州常慜禅师写大般若经感应。并州常慜禅师发大誓愿生极乐，遊京洛专崇净业，感徵遂愿写大般若经满万卷，冀得远诣西域礼如来圣迹、迴向愿生；乃蒙授墨敕、南遊江表敬写般若，后附舶西征，百千天人奏伎乐，即见乘舶是般若夹，后于天竺而卒、得净土迎。",
    "第四十六·京兆僧智讽诵大般若经感应。释僧智京兆人，其母梦见吞铜香炉而有身，生产即唱大般若名字；十岁自然谙诵大般若经二百卷、每日诵一百卷，自怪无宿习而祈念，梦一沙门告其前世受弊牛身、主人负大般若经二百卷驱向精舍，于深泥踏蹶而终生人间，以是因缘讽诵二百卷，捨此身将生雷音佛国。",
    "第四十七·并州道俊写大般若经感应。释道俊一生修念佛三昧、不乐余行，同州僧常慜劝写大般若经，俊以修念佛无暇推辞；夜梦至海滨欲附舶渡西岸，舶童子言「舶是般若，若无般若不能渡生死海、岂得生彼不退地」，俊梦觉惊怖悔过，以衣钵写抄般若，供日紫云西来、音乐闻空。",
    "第四十八·唐豫州神母闻大般若经名死更得活感应。唐豫州一老母唯事神通、不信三宝，人称神母；一黄牛入其门三日无主，女解衣带系牛鼻而牛牵入佛寺，众僧称南谟大般若波罗蜜多经，神母捨牛走出洗耳；后遭疾死，其女梦告「我死至阎魔法王处，唯恶业庄严、全无善根，因闻般若称名善还人间，遂生忉利天」，女觉而写般若三百余卷。",
    "第四十九·踏大般若经所在地离恶趣业感应。释灵运（天竺名般若提波）襄陽人，追寻圣迹至西国，于那兰陀寺画弥勒真容菩提树像；至伊烂拏鉢代多国孤山精舍刻檀观自在像前绝食祈愿，像中出妙身慰喻其三愿皆成就、当入铁塔读大般若经、踏经所在地必免三恶趣，步步灭罪、增进佛道；灵运笼居铁塔礼拜读经半年，归唐广兴佛事。",
    "第五十·释迦趣菩提树时地神奉般若金夹感应。释迦菩萨六年苦行将证正觉，登前正觉山、大地震动，山神告非成道地，须陀会天指菩提树金刚座；诸天将趣菩提树，地神于中路从地涌出、捧三寸金夹奉上菩萨，言此是先佛印函、收入般若波罗蜜法门，三世诸佛皆得此夹、由般若力降魔成道；菩萨开金夹时夹中广转十方佛土、般若印文皆反为佛放白毫光，方成正觉。",
    "第五十一·周高祖武帝大品感应。周高祖灭法、经藉从灰，后年中忽见空中如𮏄大者五六飞上空中，极目不见、全为一段随飘飘上下，久乃翻下墮士墙，视之乃是大品经之第十三卷，人皆谓希奇感应、归心者多。",
    "第五十二·阿练若比丘读诵大品经感应。昔有练若比丘读诵摩诃般若经，常夜分有天人来以天甘露供养；比丘问天上有般若否，答有；问有经卷何故来下，答为敬法故、天上般若诸天传语、人中般若正记佛言；问谁守护持般若者，答八十亿诸天来下人间守护持般若者，乃至闻一句者敬之如佛。",
    "第五十三·天水郡张志达写大品经三行延寿感应。天水郡张志达信道士不写佛经，于亲友家见人写大品般若误谓老子经、戏取写三行，知非老子经而忽起去；三年遇疾而死，一宿还活，说阎摩法王见其来、捡恶业二十余纸，唯残半纸，因其写大品般若三行有大功德、增其寿业放还；达遂捨财书写八部供养，八十三无病而卒。",
    "第五十四·晋居士周闵大品般若感应。晋周闵江南人、护军将军世奉法，苏峻之乱避难受持大品，家有大品以半幅八丈素反覆书之、又杂余经数台；当避难行仓卒不能尽持，尤惜大品不知在何台，徘徊叹息间大品忽自出外，闵惊喜持去，周氏遂世宝之。",
    "第五十五·朱士行三藏放光般若感应。前魏废帝甘露五年，颍川朱士行常讲道行般若，叹译理未尽，发迹长安、度流沙至于阗得梵书正本九十章；于阗小乘学者谮之于王，士行请烧经为验，积薪殿前焚经无损，王始归信；士行寄经还国，竺叔兰、无罗叉译为放光般若。",
    "第五十六·释清虚为三途受苦众生受持金刚般若经感应。梓州惠义寺释清虚少诵金刚般若，万岁通天元年于齐灵岩寺北三总山中发愿为三途受苦众生受持金刚般若，端坐诵经；似梦见一城，闻投门者称昨日未时齐州禅师执锡杖至王前，为三途受苦众生诵金刚般若、请王放地狱轻者，王许明日午时放却少分轻者。",
    "第五十七·僧法藏书诵金刚般若经灭罪感应。隋鄜州实室寺僧法藏武德二年得患困重，见一人持金刚般若经告其「汝互用三宝物得罪无量，若自造一卷至心诵持，一生所用三宝物罪并得消灭」；藏即写百部诵持不废，后命终至王所，以造像、写金刚般若百部、写一切经八百卷等功德，王捡功德簿不错、放其在寺劝化，乃得醒活。",
    "第五十八·唐玄宗皇帝诵仁王咒感应。唐天宝元年西蕃大石康五国来侵安西，玄宗诏请不空三藏诵仁王护国经陀罗尼二七遍，帝忽见神人五百员带甲荷戈在殿前；其年四月安西奏云二月十一日后城东北三十里云雾晦冥中有人众长丈余皆被金甲、鼓角大鸣、地动山倾经二日，五国奔溃，帐幕间有金色毛鼠齧断弓弩弦，城楼上有光明天王现形。",
    "第五十九·唐代宗皇帝讲仁王般若降雨感应。代宗永泰元年秋天下无雨枯渴，代宗诏于资圣、西明两寺请百法师讲新翻仁王般若经，以不空三藏为都讲，至九月一日黑云耸空、甘露雨降，枯死草木顿成荣茂；又羌胡寇边、京城因星变，内出仁王经二卷开百座仁王道场，皆有感应。",
    "第六十·旧译仁王经感应。德宗贞元十九年一沙门宿太山府君庙堂、诵新译经四无常偈，府君梦示「吾昔在佛前亲闻此经，什公翻译词质义味泯合，闻读诵声身心清凉；新经词甚美、义味淡薄」，沙门梦觉兼持旧本。",
    "第六十一·无量义经传弘感应。此无量义经虽法华首载其目，而中夏未睹其说；武当山惠表勤苦求道，建元三年远至岭南于广州朝亭寺遇中天竺沙门昙摩伽陀耶舍得一本，永明三年顶戴出山投弘通。一人不信此经何必法花序，梦长丈余带金甲神以利剑拟之，云此经正是法华序分、闻经者得不失菩提心，即觉悔谢。",
    "第六十二·闻无量义经功德生忉利天感应。昔惠表比丘于武当山诵无量义经，后顶戴出山投宿山中；初夜分有天来，以百千天众为眷属供养经及表，自称是武当青雀、聚闻无量义经命终生忉利天、欲报恩故来供养，本身在山西南隅一处聚集捨身；表遣使寻青雀聚，实如所言。",
    "第六十三·诵法华经满一千部必有灵验感应。齐武成世并州东看山侧有人掘地，见一物状如人两唇、中有舌鲜红赤色，以闻奏帝；沙门大綩法师奏此是持法华者六根不坏报、诵满千遍必有征验；集持法华者围绕诵经，纔始发声此灵唇舌一时鼓动，闻见毛竖，诏遣石函藏之。",
    "第六十四·书写法花经满八部必有救苦感应。宋瓦官寺沙门惠道（释惠果同母之弟）生不修行业、善兴贩、私用众物割盗，遇疾而死、三日苏，说冥官被驱，有沙门教其言「我昔有造法花八部愿」；至王所答此，王笑言「既云有愿，若造法花及八部者必脱八狱」，依此一言还放人间，遂捨所有造八部。",
    "第六十五·书写法华经一日即速救苦感应。绛州孤山永徽年中二僧（僧行修三阶佛法、僧法修法花三昧）要期先亡者必告所；僧行先亡三年后僧法祈请观音，梦至地狱见七重铁网、铁扉，百千犯戒沙门受苦，见僧行身体烧烂，告其「为造法花经，一日之中可毕其功」；法梦觉即日捨衣钵、以书手四十人一日写之供养，夜梦僧行离地狱苦近生忉利天。",
    "第六十六·七卷分八座讲法花经感应。释惠明讲法华经天机独断，入深山坐石室讲经，数群猿猴来听；三月后夜石窟上有光明，是天人（猿猴群中老弊而盲者）依闻讲生忉利天、思师恩来听；天人请以一部典分八而讲（谓法华是八年说、开八座拟八岁说略可佛旨），明即分七卷成八轴为天开讲，天以八枚真珠奉施说偈，明具记事彫石收藏。",
    "第六十七·昙摩忏三藏传大涅槃经感应。晋安帝世中天竺三藏昙摩忏（法丰）赍大涅槃前分十卷并菩萨戒等到姑臧，止传舍、枕经而寝，夜有人牵其堕地凡三夕，闻空中声「此如来解脱之藏，何为枕之」；忏渐悟，别安高所，盗者数举竟不能胜，明旦忏特不以为重，盗者谓为圣人悉来辞谢。",
    "第六十八·释惠严删治涅槃感应。宋释惠严嫌大涅槃经文字繁多、遂加刊削就成数卷，梦一人身长二丈余责「涅槃尊经众藏之宗，何得轻加斟酌」；次夕复见其人怒色言「过而知改是谓非过」「此经既无片理，且君祸亦将及」；严惊觉失声，未及中旦便驰信求还悉烧除之。",
    "第六十九·书写涅槃经生不动国感应。尚书刑部侍郎张行安发愿写涅槃经，始立题夜梦二沙门来云「汝写深经，决定生不动国佛土」；行安觉而专志写之。",
    "第七十·闻常住二字感应。杨州一居士不信大般涅槃常住佛性理，闻「常住」二字不堕恶道而生不信；后微疾而死、七日醒，云至阎魔天子城，王呵其谤深经报在阿鼻，居士忆持因果白王「设谤故堕恶道，闻常住二字故亦可闭恶道门户」，空中忽有光现、光中说偈「若信若不信，纔闻常住字，决定不堕恶，即生不动国」；王欢喜放还，居士流淚修行，临终得不劝国迎。",
    "第七十一·手触涅槃经感应。昔西域一婆罗门从手放光，人异之问阿罗汉不知因缘，后得通大士来见放光云「善哉婆罗门，昔以手触涅槃尊经，以是因缘能放光明，汝未来得佛亦名光明尊」。",
    "第七十二·诸王写一切经感应。齐高宗明帝写一切经，陈高祖武帝写一切经十二藏、世祖文帝写五十藏、高宗宣帝写十二藏，魏太祖道武皇帝写一切经，齐肃宗孝明帝为先皇写一切经十二藏合三万八千四十七卷，隋高祖文帝写十六藏十三万三千八十六卷、炀帝写六百一十二藏二万九千一百七十二部，皆有感应不能备记。",
    "卷下·僧宝聚目录（第一文殊师利菩萨得名感应，至第四十二淄州释惠海画无著世亲像得天迎感应）。",
    "卷下卷首题记：释子非浊集。",
    "第一·文殊师利菩萨感应。文殊师利旧云妙德、新云妙吉祥，立名有二：一就世俗因瑞彰名，菩萨生舍卫国梵德婆罗门家、从母右胁而生，身紫金色、堕地能语，有七宝盖随覆，具十种感应（天降甘露、地涌伏藏、仓变金粟、庭生金莲等）故名妙吉祥；二依胜义立名，如金刚顶经说由菩萨身普摄一切法界如来身故名妙吉祥。",
    "第二·文殊化身为贫女感应。昔一贫女携抱二子、一犬随行，剪发以施赴齐会，主僧依次与食三倍，贫女复求与犬、又言腹中有子须食，僧愤叱令去；贫女即时离地化作文殊像，犬为师子、二儿即善财及于阗王，五色云气遍空，留偈「苦瓠连根苦，甜瓜彻蒂甜，是我超三界，却被阿师嫌」而隐；主僧恨不识真圣欲割目，众人劝止，遂以贫女所施之发于菩萨乘云起处建塔供养。",
    "第三·阿育王造文殊像感应。昔阿育王统摄此洲、学鬼主制狱，作地狱、凶人为狱卒；文殊现处镬中，火炽水清、生青莲花，王心感悟即日毁狱，八万四千夫人同入火坑，八万四千塔建立形像其数亦八万四千，此土东晋庐山文殊金像即其一。",
    "第四·照果寺解脱禅师值文殊感应。五台县照果寺释解脱常诵法华、作佛光等观，追寻文殊再三逢遇；问文殊如何利益此土难化众生，文殊告其一日三时入破散众魔、入智母三昧破愚痴暗，往地狱现作佛身放光说法、往饿鬼城施食、入畜生道除愚痴；又问何众生得化度，答画我形像、造我形像、口称南无者易可化度，余者虽尽悲心以自业故难化。",
    "第五·释智猛画文殊精诚供养感应。释智猛少甚愚痴、都无分别心，其父用钱三十文画文殊像令其子对像，梦像放光照儿顶、光入顶，觉后有自然辩智，如学法长年比丘；出家之后才智超人号曰智猛，文殊化作梵僧来此土谒智猛。",
    "第六·五台县张元通造文殊形像感应。张元通信心贞固、发愿造文殊像高三尺供养，夜三更梵僧执香炉来绕像三匝不见，像放光至五更；梦十方诸佛来集室内以妙花供养形像，言「是我本师，以敬师故我等供养」，并以妙璎珞供养元通；佛言十方世界凡造文殊像者诸佛皆供养之，因我等发心皆是文殊教化力。通后见圣众来迎，生金色世界。",
    "第七·宋路照太后造普贤菩萨像感应。宋路照太后大明四年造普贤菩萨乘宝舆白象像安中兴禅房，十月八日解坐会集僧二百人；是日忽有一僧豫于座次、风毘秀举，齐主与之交谈往复百余言而忽不复见，列筵同睹，识其为神人。",
    "第八·窥冲法师造普贤像免难到印度感应。窥冲法师交州人，志望达印度，发愿造普贤像祈请；梦普贤乘白象摩其顶言「汝有诚志将往印度，若有留滞我必救」；与明远同舶泛南海遭恶风欲墮罗刹国，专念普贤而其像现舶上，风静向狮子国，又遭摩竭鱼难、专念普贤像现而大鱼合口而去，免难到师子国、西印度，礼菩提树、竹林园，遇微疾如梦普贤告依圣力满足本愿。",
    "第九·高陲秦安义蒙普贤救疗感应。高陆秦安义自少放鹰射猎为业、杀生不可计，五十八岁忽发疮病、脓血秽身臭气，疮疱皆似雉嘴；请僧道俊法师，俊言此是鹰猎罪报、须懺罪造普贤像，义闷绝气绝，亲属造像修普贤懺，三日方醒，说见马头牛头、所杀雉鸡鹿羊各诉命，阎王依诉状召问，有沙门（普贤）来救、称是檀越，王放还；义愈后捨所有供养其像、刎髮出家，诫子孙莫犯重罪。",
    "第十·上定林寺释普明见普贤身感应。齐上定林寺释普明以忏悔为业、诵法华，每至劝发品辄见普贤乘白象王在其前。",
    "第十一·乌长那国达丽罗川中弥勒木像感应。北印度乌长那国达丽罗川中有精舍刻木弥勒像、金色灵异长十丈余，为佛灭后末田地大阿罗汉所造；尊者念众生依何见真容，即以神力携引工匠三返升兜率天面见真相方造像；弥勒告其以天眼观见三千大千世界造我像者密遣青衣冥资其功、彼人决定不堕恶道，成佛时其像为前导。",
    "第十二·济阳江夷造弥勒像感应。晋戴逵（安道）之子戴颗（仲若）继志巧制像，济阳江夷少与颗友、托颗造观世音像，相好不圆积年无成；后梦有人告「江夷于观音无加，可改为弥勒菩萨」，戴即停手欲报江而未发而江书已至，俱于此夕感梦符同；戴改为弥勒，应手成妙、光颜圆满。",
    "第十三·释沿谔造弥勒菩萨感应。释沿谔少有义学喜誉、常愿生兜率天，作兜率天宫观、注义源四卷；梦青衣童子告其欲生兜率奉见慈氏当造形像观真容，觉即刻木为像，七十余岁卒，临终告徒众「我所造像现虚空中，从像生天」。",
    "第十四·释诠明法师造慈氏檀像感应。释诠明法师发愿造三寸刻檀慈氏菩萨像、祈誓生兜率天，著上生经抄四卷；梦其像渐长大金色光明、对其微笑，明问「我等愿求生兜率天将得生不」，像言「我既得释迦文大师要势付属，不念尚不捨之，况有念愿」；临终傍人梦见百千青衣人来迎，明指天而去。",
    "第十五·菩提树下两躯观自在像感应。佛涅槃后诸国王君闻佛说金刚座量，遂以两躯观自在菩萨像南北标界、东西而坐；耆旧相传此菩萨像身没不见则佛法当尽，今南隅菩萨没过臆矣。",
    "第十六·摩揭陀国孤山观自在菩萨像感应。摩揭陀国孤山精舍有观自在菩萨像、威神盛肃，常有数人断食求见，有感者见菩萨妙相从像中出慰喻；玄奘法师买花为鬘至像前至诚礼赞、发三愿（归国平安、愿生睹史多宫事慈氏、问众生有无佛性者），花皆如言住手、挂臂、挂颈，感得如言。",
    "第十七·戒贤论师蒙三菩萨诲示感应。玄奘至摩诃陀国世无厌寺遇戒贤（正法藏），贤命觉贤为众说其三年前病恼因缘：戒贤昔患风病二十余载，痛苦难忍欲不食取书，夜梦三天人（金黄、琉璃、白银色）劝其不可厌身、宜观宿愆至诚忏悔、于苦安忍、勤宣经论，并指示金色者自称曼殊室利、碧色者观自在、银色者慈氏；戒贤问常愿生尊处得不，慈氏答「广传正法后当生」，曼殊劝显扬瑜伽论等。",
    "第十八·戒日王子感自在像感应。东印度金耳国王月害、羯若鞠阇国王王增，大臣劝先王之子戒日继位，戒日不许，诣兢伽河岸观自在菩萨像前断食祈请；菩萨现形告其先身在此林中为兰若比丘精勤不懈、承福力为王子，金耳国王既毁佛法，汝绍王位宜重兴隆，不久当王五天竺境；戒日受教袭位，一一如圣言，三十年兵戈不起。",
    "第十九·南天竺尸利密多菩萨观音灵像感应。秦姚兴京兆沙门释智猛至南天竺尸利密多罗菩萨塔，侧有破精舍中有金色观世音菩萨像、雨霜不湿；耆旧传昔尸利密多菩萨最悲三途众生、造观世音像三年功毕，灵像感通：夜二更放光明，光中见十八泥犁、三十六饿鬼城、四十亿畜生受苦，灵像现百千金甲军入十八泥犁摧破镬器、苦具断坏，地狱反作凉池、苦器悉作莲花，狱卒恐怖、阎王叹不及。",
    "第二十·晋居士刘度等造立观音形像免苦感应。晋刘度平原辽城人，乡里千余家奉法、造立形像供养僧尼；县常有逋逃，未大怨欲尽灭一城，众凶惧，度乃洁诚率众归命观世音，顷之物从空下绕所住屋柱、惊视乃观世音经，使人读之，未大欢喜、省刑戮，此城得免害。",
    "第二十一·释道秦念观世音菩萨增寿命感应。魏常山衡唐精舍释道秦，梦见当终四十二岁，及至其年遇重病，友人言「供养六十亿菩萨与一称观世音福同无异」，秦乃四日四夜专精归依；所坐帷下忽见光明从户外而入、见观音足趺踝间金色朗照，语秦机感之理，秦褰帷不见，悲喜流汗、体轻而愈、终延年。",
    "第二十二·鲁郡孤女供养观世音朽像感应。鲁郡一孤女于麦田中见朽木似圣像、收置草屋，以所食上分供养，后遭疾而终、一日一夜还活，说死后被抱火车持去，有一沙门五体损坏代其受苦、持车人合掌放还，沙门言「我是观世音，麦田中朽木即我像也」；女遂以屋地施精舍、以身眼造观世音像啼泣供养。",
    "第二十三·憍萨罗国造十一面观音像免疾疫难感应。佛灭度后八百年中憍萨罗国疾疫流行、病死半分，经三年不得免难；王臣共议立誓祈请十方世界大悲者，梦见圣像具足十一面、身黄金色、舒手摩王顶言「我以十一面守护王国」；王臣人民一日中造十一面观音像，一时免难，此后百年未遭此难。",
    "第二十四·造千臂千眼观自在像法延寿感应。昔婆罗奈国一长者仅有一子、寿合十六，一婆罗门教作千臂千眼观自在像法、用千臂咒一日一夜，得阎魔王报「长者子寿只今十六，今遇善缘得年八十」；长者夫妻欢喜，罄舍家资施众僧。",
    "第二十五·罽宾国行千臂千眼像法免难感应。昔罽宾国有疾病流行、人得病不过一二日并死，有婆罗门真谛将此千臂千眼像法施行，救疗应时消灭，行病鬼王出于国境。",
    "第二十六·大婆罗门家诸小儿等感千手千眼观音像感应。昔一沙门次第乞食至大婆罗门家，时其家屋栋梁摧折、打破瓶器、牛马奔逸，婆罗门谓为不祥之人；沙门问其家儿子等腹胀面肿、身重眼暗为疾鬼所恼否，婆罗门言先见之，沙门言家中有恶鬼夜叉吸人精气、以畏我故逃避，婆罗门因亲近如来大法、负千手像有此威神，时儿子诸恼方除，夫妇欢喜供养。",
    "第二十七·南印度国造不空羂索像感应。南印度国荒废、君臣不保寿、人民已丧，王遣使请中天竺尸利蜜多救国之灾；蜜多白王言有大圣不空羂索观自在大王，方造像安城西南阁，王即造像，像放光明照一由旬，王臣保寿、五谷丰饶、人民从余国来感其像，遂移阁为寺。",
    "第二十八·凉州姚徐曲为亡亲画观自在像感应。凉州徐曲（姓姚）少丧父母、长闻报恩流泪，画千手千眼观自在、六观自在像于旧宅供养，一年半无感；次年七月十四日夜空中有声自称是其双亲，因造恶业堕地狱吞热铁丸，去年二月六口沙门入地狱说法、令百千人得生天上，徐曲遂识其恩；曲以藏中黄箱金钱百丸为据知是父母，喜喜交集。",
    "第二十九·荆州赵文侍为亡亲画六观音感应。荆州赵文侍父母邪见不信三宝，侍事观世音，父母亡后雇巧手图六观世音像欲救六道；夜梦六观音，大悲观世音告其父在大焦热地狱、图我像我往彼地狱放光说法救苦，大慈观音告母在饿鬼、我往彼处手雨甘露令饱满说法；六观音各说救六道义，觉后图彩放光，后梦二丈夫（父母）乘紫云来告蒙观音救济往生净土。",
    "第三十·梁朝汉州善寂寺观音地藏画像感应。梁朝汉州德阳善寂寺东廊壁上张缯彩画观音、地藏各一躯，时人瞻礼异光焕发；麟德元年寺僧就壁摸写供养护光无异，展转摸写者甚众；麟德三年玉记任资州刺史摸写精诚供养，同行十船遇恶风九船没、唯玉记船无恐怖，天后敕画人摸写于内道场供养；后有商人妻怀孕二十八月不产，睹光明摸写发愿，当夜生一男。",
    "第三十一·雍州鄠县李赵待为亡父造大势至像感应。李赵待雍州鄠县人，其父发恶见拨无佛法、梦感神责吐血而死；赵待归心大势至、念佛救父苦，造三尺势至金像，始刻之日大地振动，二月功毕梦金人（大势至）告其造像请赴之验，谓「汝造形像兼修念佛，其父离地狱苦，我授手送净土」，待悲喜修念不废。",
    "第三十二·地藏菩萨过去为女人寻其母生处救苦感应。过去阿僧祇劫觉花定自在王如来像法中，一婆罗门女宿福深厚、其母信邪轻三宝堕地狱；女卖家宅广求香花供先佛塔寺、端坐念佛名一日一夜，忽见自身到海边见大铁围山西面第一重海沸水恶兽、罪人出没，鬼王无毒告此是阎浮提造恶新死者所感；问母生处，答其母悦帝利罪女承孝子设供修福已生天三日，此日罪人悉同生天。婆罗门女即于塔像前立誓愿尽未来劫广设方便解脱罪苦众生——即地藏菩萨。",
    "第三十三·唐益州法聚寺地藏菩萨画像感应。唐益州郭下法聚寺画地藏菩萨像（本像是张僧繇画），麟德二年寺僧图得一本放光乍出没如金环，展转图写者类皆放光；当年八月敕追一本入宫供养，京城内外俗画供养并皆放光。",
    "第三十四·唐蕳州金水县刘侍郎家杖头地藏感应。蕳州金水县刘侍郎途中拾一杖、见头刻像持归插壁中多年，后遭疾而死、心胸少暖不葬，一日二夜还活，说被冥官驱至王厅，一沙门（地藏菩萨）来救、称是侍郎年来施主，王放还；沙门言「汝平生时途中见我像持归置壁中，能忆念不忘」，侍郎遂刻彩高五寸像放光，捨家为精舍号地藏院。",
    "第三十五·地藏菩萨救乔提长者家恶鬼难感应。如来在灵鹫山时地藏菩萨游行教化，至毘富罗山下乔提长者家，其家五百人被恶鬼夺精气闷绝数日；地藏菩萨悯而往佛前请设救济之法，白佛言过去烧光王佛像法中己住凡夫地、于俱特罗山从仙人得降伏恶鬼之法，仙人授记其名地藏、当于五浊世化身救度众生；世尊听许，菩萨往救五百余人一时还活。",
    "第三十六·弥提国王画五大力像免鬼病感应。佛灭度后千三百年中弥提国百鬼乱入、疾疫流行，智臣劝王图五大力菩萨像设仁王斋会；初年月八日敕国中人民画五大力菩萨，夜初更彩色方满，金刚波罗蜜多等五菩萨各放五色、白、青、琉璃、金色光，照耀一国如昼，诸恶鬼神见光出国，病者消除，此后每年初年月八日设仁王斋会供养五大力菩萨像，三百年相续不绝。",
    "第三十七·唐益州法聚寺释法安画灭恶趣菩萨像感应。释法安住法聚寺修方等懺累日无应，请像前啼哭自责，梦异冠神告其犯用常住僧物罪难灭，更有方便即画灭恶趣菩萨像、专诵随求明，罪渐微薄、行方等忏悔障除可见化身；安觉而更画灭恶趣菩萨像、专修忏悔，闭目即得见化佛，六十七而卒。",
    "第三十八·代州总因寺释妙运画药王药上像感应。释妙运住总因寺诵法华经为业、常愿生兜率天奉事弥勒，更画药王、药上二菩萨像祈愿感应；七十余岁微疾，语师友「化佛来迎」，谓画药王药上二像、若有人识二菩萨名字者一切人天亦应礼拜，不久必生兜率内院奉事慈氏，不久而卒。",
    "第三十九·陀罗尼自在王菩萨于地狱镬缘上说法救苦感应。唐真寂寺沙门惠生（惠如禅师弟子）诵大乘，一日一夜不动如入禅定，及晓开眼悲喜交集、流淚汗血；自言被请阎魔王宫，王令观地狱，见三十二大城中皆有地狱、受苦者多是沙门，于铁镬缘上一沙门说法，自称陀罗尼自在王菩萨，为诸贪着世利、犯佛戒品、虚受信施、不净说法之沙门随所说法令忆犯罪业、愧懺厌离悔过。",
    "第四十·马鸣龙树师弟感应。昔迦叶佛世一长者轮秀有女殊他，各以七宝献佛请副恩，佛告其十七日当得成就；女梦日轮、满月入腹，经九月生二子（日珠、月镜），才至七日即便出家诣迦叶佛修法，常愿生生不相离、互为师弟子。昔日珠即今马鸣菩萨，二人不相离俱行、出现本迹利益众生；金剛正智经中马鸣过去成佛号大光明佛、龙树名妙云相佛。",
    "第四十一·释道诠禅师造龙树菩萨像生净土感应。释道诠少有义学、以智度论为心要、以龙树为师宗，发愿生安乐国，造三尺龙树形像香花供养专心祈愿；梦一沙门（龙树付法藏中第十三）告其净土业必成、却后三年往生，并白阿弥陀佛还告其师友生净土之期；后二十三年正月十五卒，父母师友皆同佛记，临终紫云盖菴、音乐闻空。",
    "第四十二·淄州释惠海画无著世亲像得天迎感应。释惠海洞法相源、朗经法宗，自画无著、世亲像，思慕所释深妙；梦二童子告其当生兜率天、所图无著世亲在彼天上为慈氏侍者，海从童子往兜率天内院见慈氏及无著世亲，慈氏使二侍者为释其疑；海下天广弘佛教、秘不告人，没后遗书中载之。末附作者偈颂，回施法界有情同证菩提。",
]
assert len(YIJIE) == 171, f'YIJIE mismatch: {len(YIJIE)}'

translations = []
for i in range(171):
    section = '【' + TITLES[i] + '】'
    modern = section + '【义解】' + YIJIE[i] + '【正文】' + paras[i]
    translations.append({'section': section, 'original_preview': paras[i], 'modern': modern})

for i, t in enumerate(translations):
    m = t['modern']
    assert m.startswith('【'), f'seg{i+1} not start with 【'
    assert '【义解】' in m and '【正文】' in m, f'seg{i+1} missing 义解/正文'
    yi = m.index('【义解】'); zw = m.index('【正文】')
    assert zw > yi and len(m[zw + 4:].strip()) > 0, f'seg{i+1} 正文为空'

out = {
    'id': TID, 'title': TITLE, 'translator': TRANS, 'mode': 'baihua',
    'intro': INTRO, 'sutraPath': '../sutras/' + TID + '.json', 'translations': translations,
}
os.makedirs('data/modern-translation', exist_ok=True)
with open(f'data/modern-translation/{TID}.json', 'w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=2)
print('OK', TID, len(translations), '段')
